#include <stdio.h>
#include <stdlib.h>

int main(void) {
    const int width = 320, height = 180, bytes = width * height * 3;
    unsigned char *frame = malloc(bytes);
    if (!frame) return 2;
    long index = 0;
    while (fread(frame, 1, bytes, stdin) == (size_t)bytes) {
        int magenta = 0, orange = 0, periwinkle = 0;
        int yellow = 0, light_green = 0, white = 0, red = 0, blue = 0;
        for (int i = 0; i < bytes; i += 3) {
            int r = frame[i], g = frame[i + 1], b = frame[i + 2];
            if (r > 150 && b > 100 && g < 110 && r > g * 2) magenta++;
            if (r > 170 && g > 70 && g < 190 && b < 100 && r > g + 50) orange++;
            if (b > 150 && r > 70 && r < 210 && g > 70 && g < 210 && b > r + 25 && b > g + 25) periwinkle++;
            if (r > 180 && g > 180 && b < 130) yellow++;
            if (g > 190 && r > 50 && r < 190 && b > 40 && b < 190 && g > r + 50 && g > b + 50) light_green++;
            if (r > 225 && g > 225 && b > 225) white++;
            if (r > 180 && g < 80 && b < 80) red++;
            if (b > 170 && r < 100 && g < 130) blue++;
        }
        if (magenta > 400 || orange > 400 || periwinkle > 400 ||
            yellow > 250 || light_green > 800 || white > 3000 ||
            red > 3000 || blue > 3000) {
            printf("%ld %d %d %d %d %d %d %d %d\n", index, magenta, orange,
                   periwinkle, yellow, light_green, white, red, blue);
        }
        index++;
    }
    free(frame);
    return 0;
}

