import json
from pathlib import Path
p = Path('output/solution.json')
data = json.loads(p.read_text())
assert set(data) == {'episodes'} and len(data['episodes']) == 6
expected_eps = [f'episode_{i:02d}' for i in range(1, 7)]
assert [e['episode_id'] for e in data['episodes']] == expected_eps
weapons = {'pistol','shotgun','chaingun','rocket_launcher','plasma_rifle'}
keys = {'blue_key','yellow_key','red_key'}
switches = {'switch_amber','switch_cyan','switch_violet','switch_white'}
doors = {'door_blue','door_yellow','door_red'}
checkpoints = {'checkpoint_alpha','checkpoint_beta'}
types = {'key_pickup','weapon_pickup','switch_activate','checkpoint_activate','locked_door_open','checkpoint_restore','level_exit'}
entities = {
  'key_pickup': keys,
  'weapon_pickup': weapons - {'pistol'},
  'switch_activate': switches,
  'checkpoint_activate': checkpoints,
  'locked_door_open': doors,
  'checkpoint_restore': checkpoints,
  'level_exit': {'episode_exit'},
}
for ep in data['episodes']:
    assert set(ep) == {'episode_id','events'}
    assert ep['events'] and ep['events'][-1]['event_type'] == 'level_exit'
    ts = []
    for ev in ep['events']:
        assert set(ev) == {'timestamp_ms','event_type','entity_id','state'}
        assert isinstance(ev['timestamp_ms'], int) and ev['timestamp_ms'] >= 0
        assert ev['event_type'] in types and ev['entity_id'] in entities[ev['event_type']]
        ts.append(ev['timestamp_ms'])
        st = ev['state']
        assert set(st) == {'active_weapon','held_keys','active_switches','open_doors','current_checkpoint'}
        assert st['active_weapon'] in weapons
        assert set(st['held_keys']) <= keys and len(st['held_keys']) == len(set(st['held_keys']))
        assert set(st['active_switches']) <= switches and len(st['active_switches']) == len(set(st['active_switches']))
        assert set(st['open_doors']) <= doors and len(st['open_doors']) == len(set(st['open_doors']))
        assert st['current_checkpoint'] is None or st['current_checkpoint'] in checkpoints
    assert ts == sorted(ts)
print('validated', sum(len(e['events']) for e in data['episodes']), 'events')
for ep in data['episodes']:
    print(ep['episode_id'], len(ep['events']), ep['events'][-1]['timestamp_ms'])
